// Cloudflare Worker entry (feature 7, D23; card text D29): adapts the Workers
// runtime to the pure handlers in ask.ts and cards.ts. The Gemini key is a
// Wrangler secret and never ships in the app.

// Generated by `npm run grounding` (gitignored: rulebook text and Discord-derived
// rulings aren't ours to republish).
// eslint-disable-next-line import/no-unresolved
import rulingsJson from './dev-rulings.generated.txt';
// eslint-disable-next-line import/no-unresolved
import grounding from './grounding.generated.txt';

import { handleAsk, type AskEnv, type RateLimiter } from './ask.ts';
import {
  loadIndex,
  refreshCards,
  rulesWordsFrom,
  type CardIndex,
  type StoredIndex,
} from './cards.ts';
import type { DevRuling } from './devRulings.ts';

interface KV {
  get(key: string, type: 'json'): Promise<unknown>;
  put(key: string, value: string): Promise<void>;
}

interface Env extends AskEnv {
  ASK_LIMITER: RateLimiter;
  /** Card store (D29): one key, "cards", holding a StoredIndex. */
  CARDS?: KV;
}

const CARDS_KEY = 'cards';
const CACHE_MS = 10 * 60 * 1000;

// Module scope runs once per isolate, outside the per-request CPU budget.
const rulings = JSON.parse(rulingsJson || '[]') as DevRuling[];
const rulesWords = rulesWordsFrom(grounding);
let cache: { index: CardIndex | null; at: number } | null = null;

async function cardIndex(env: Env): Promise<CardIndex | null> {
  if (cache && Date.now() - cache.at < CACHE_MS) return cache.index;
  const stored = (await env.CARDS?.get(CARDS_KEY, 'json')) as StoredIndex | null | undefined;
  cache = { index: stored?.v === 1 ? loadIndex(stored, rulesWords) : null, at: Date.now() };
  return cache.index;
}

const HEADERS = { 'user-agent': 'CasterCompanion-rules-worker/1.0' };

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const { status, body } = await handleAsk(
      {
        method: request.method,
        path: new URL(request.url).pathname,
        header: (name) => request.headers.get(name),
        ip: request.headers.get('cf-connecting-ip') ?? 'unknown',
        bodyText: () => request.text(),
      },
      env,
      {
        fetch: (input, init) => fetch(input, init),
        limiter: env.ASK_LIMITER,
        grounding,
        cards: () => cardIndex(env),
        rulings,
      },
    );
    return Response.json(body, { status });
  },

  /** Cron (D29): pick up new cards from the sitemap, a couple per run. */
  async scheduled(_event: unknown, env: Env): Promise<void> {
    const kv = env.CARDS;
    if (!kv) return;
    const result = await refreshCards({
      fetch: (url) => fetch(url, { headers: HEADERS }),
      get: async () => (await kv.get(CARDS_KEY, 'json')) as StoredIndex | null,
      put: (index) => kv.put(CARDS_KEY, JSON.stringify(index)),
    });
    if (result.added.length > 0 || result.pending !== 0) console.log('cards refresh', result);
  },
};
